use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use reqwest::Client;
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Deserialize)]
struct RedirectParams {
    url: Option<String>,
    callback: Option<String>,
}

#[derive(Deserialize)]
struct FetchParams {
    target: String,
}

// Internal service registry for microservice communication
struct ServiceRegistry {
    endpoints: HashMap<String, String>,
}

impl ServiceRegistry {
    fn new() -> Self {
        let mut endpoints = HashMap::new();
        endpoints.insert("metadata".to_string(), "http://169.254.169.254".to_string());
        endpoints.insert("internal-api".to_string(), "http://10.0.1.50:8080".to_string());
        ServiceRegistry { endpoints }
    }
}

async fn handle_redirect(params: web::Query<RedirectParams>) -> HttpResponse {
    // OAuth callback handler - redirects user after authentication
    if let Some(ref url) = params.url {
        // Validate that URL starts with expected scheme
        if url.starts_with("http") {
            return HttpResponse::Found()
                .append_header(("Location", url.as_str()))
                .finish();
        }
    }
    if let Some(ref callback) = params.callback {
        // Legacy callback support
        return HttpResponse::Found()
            .append_header(("Location", callback.as_str()))
            .finish();
    }
    HttpResponse::BadRequest().body("Missing redirect URL")
}

async fn fetch_internal(
    params: web::Query<FetchParams>,
    client: web::Data<Client>,
) -> HttpResponse {
    // Server-side fetch for internal service mesh communication
    // Used by frontend to aggregate data from internal microservices
    let target = &params.target;

    // Block obvious metadata endpoint access
    if target.contains("169.254.169.254") && target.contains("/latest/meta-data") {
        return HttpResponse::Forbidden().body("Direct metadata access blocked");
    }

    // Allow fetching from any URL (needed for service mesh)
    match client.get(target.as_str())
        .timeout(std::time::Duration::from_secs(5))
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body = resp.text().await.unwrap_or_default();
            HttpResponse::build(actix_web::http::StatusCode::from_u16(status.as_u16()).unwrap())
                .body(body)
        }
        Err(e) => HttpResponse::BadGateway().body(format!("Fetch failed: {}", e)),
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let client = Client::builder()
        .redirect(reqwest::redirect::Policy::limited(10))
        .build()
        .expect("Failed to create HTTP client");

    let _registry = ServiceRegistry::new();

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(client.clone()))
            .route("/auth/callback", web::get().to(handle_redirect))
            .route("/api/fetch", web::get().to(fetch_internal))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
